package net.imadz.codegen.scaffolding.cqrs.template.products

import net.imadz.codegen.scaffolding.cqrs.model.products._
import net.imadz.codegen.structure.NamingConventions

object ProductActorTemplate {
  def generate(model: ProductDomainModel, externalIngress: Boolean = false): Vector[ProductSourceModel] = model.aggregates.map { a =>
    val pkg = model.packages(a.declaration.ref.context)
    val name = NamingConventions.productSymbol(a.declaration.ref.id)
    val commands = a.commands.map(c => "            case p: " + NamingConventions.productSymbol(c.command.id) + " => " + name + "Rules." + NamingConventions.productSymbol(c.command.id) + "(state, p, hosts)\n").mkString
    val external = if (externalIngress) a.external else Vector.empty
    val messages = external.map(p => "  final case class Ingest" + NamingConventions.strictSymbol(p.id) + "(output: " + model.packages(p.outputType.asInstanceOf[net.imadz.meta.products.NominalType.Named].ref.context) + ".domain.values." + NamingConventions.productSymbol(p.outputType.asInstanceOf[net.imadz.meta.products.NominalType.Named].ref.id) + ", authorization: String, replyTo: ActorRef[Reply]) extends Request\n").mkString
    val authority = if (external.nonEmpty) "  trait ExternalAuthority { def authorize(producer: String, authorization: String, identity: Vector[String]): Boolean }\n" else ""
    val authorityParam = if (external.nonEmpty) ", authority: ExternalAuthority" else ""
    val ingress = external.map(p => "        case Ingest" + NamingConventions.strictSymbol(p.id) + "(output, authorization, reply) =>\n          if (!authority.authorize(" + ujson.write(p.id) + ", authorization, " + name + "ExternalEvents." + NamingConventions.strictSymbol(p.id + "_identity") + "(output))) Effect.none.thenRun((_: " + name + "State) => reply ! Refused(\"external-authority-denied\"))\n          else Effect.persist(" + name + "ExternalEvents." + NamingConventions.strictSymbol(p.id) + "(output)).thenRun((_: " + name + "State) => reply ! Accepted(Vector(" + name + "ExternalEvents." + NamingConventions.strictSymbol(p.id) + "(output))))\n").mkString
    val content = "package " + pkg + ".domain\n\nimport akka.actor.typed.{ActorRef, Behavior}\nimport akka.persistence.typed.PersistenceId\nimport akka.persistence.typed.scaladsl.{Effect, EventSourcedBehavior}\nimport " + name + "Protocol._\n\n" +
      "object " + name + "Aggregate {\n  sealed trait Request\n  final case class Execute(command: Command, replyTo: ActorRef[Reply]) extends Request\n  final case class GetState(replyTo: ActorRef[" + name + "State]) extends Request\n" +
      "  sealed trait Reply\n  final case class Accepted(events: Vector[Event]) extends Reply\n  final case class Refused(code: String) extends Reply\n" + messages + authority +
      "  def apply(persistenceId: String, initial: " + name + "State, hosts: " + name + "Computations" + authorityParam + "): Behavior[Request] = {\n" +
      "    require(persistenceId != null && persistenceId.nonEmpty && hosts != null" + (if (external.nonEmpty) " && authority != null" else "") + ", \"explicit persistence identity and implementations required\")\n" +
      "    EventSourcedBehavior[Request, Event, " + name + "State](PersistenceId.ofUniqueId(persistenceId), initial,\n" +
      "      (state, request) => request match {\n" + ingress + "        case GetState(reply) => Effect.none.thenRun((s: " + name + "State) => reply ! s)\n        case Execute(command, reply) =>\n          val decision = command match {\n" + commands +
      "          }\n          decision match {\n            case Left(code) => Effect.none.thenRun((_: " + name + "State) => reply ! Refused(code))\n            case Right(events) => Effect.persist(events).thenRun((_: " + name + "State) => reply ! Accepted(events))\n          }\n      },\n      (state, event) => " + name + "EventHandler(state, event))\n      .eventAdapter(" + pkg + ".infrastructure.serialization." + name + "EventAdapter)\n      .snapshotAdapter(" + pkg + ".infrastructure.serialization." + name + "SnapshotAdapter)\n  }\n}\n" +
      "object " + name + "AggregateFactory { def create(persistenceId: String, initial: " + name + "State, hosts: " + name + "Computations" + (if (external.nonEmpty) ", authority: " + name + "Aggregate.ExternalAuthority" else "") + "): Behavior[" + name + "Aggregate.Request] = " + name + "Aggregate(persistenceId, initial, hosts" + (if (external.nonEmpty) ", authority" else "") + ") }\n"
    ProductSourceModel(NamingConventions.productPackagePath(pkg, "domain/" + a.declaration.ref.id + "Aggregate.scala"),
      "// @generated by CodegenMain:semantic-products-1\n" + content, "aggregate", Vector(a.declaration.source) ++ a.commands.map(_.source), model.footprint)
  }
}
